-- FRESH DB ONLY. Phase 108 tests (Bangla wording fixes of the label_bn / label_mix seed rows 72..103, generated by tools/apply_bangla_review.py).
--   Build: bash tests/sql/final_build.sh <db> "<canonical order ... phase103 phase108>"   (phase108 pasted last; tests/sql/run_all_sql.sh appends it)
--   Run from the REPO ROOT (the blocks below paste phase108.sql again):
--     psql -h /tmp -p 5544 -U postgres -d <db> -qAt -f supabase/phase108_test.sql | grep -E "FAIL|RESULT"
\set ON_ERROR_STOP off
create schema if not exists tt;
create table if not exists tt.res (name text, ok boolean);
truncate tt.res;
create or replace function tt.chk(p_name text, p_ok boolean) returns void language plpgsql as $$
begin insert into tt.res values (p_name, coalesce(p_ok,false)); raise notice '% %', case when coalesce(p_ok,false) then 'PASS' else 'FAIL' end, p_name; end $$;

-- T1 the migration changed the sample rows to the reviewed text
select tt.chk('T1 rule production_requires_cost: label_bn carries the reviewed cost word (কস্ট), not খরচ',
  (select label_bn from public.rules where key = 'production_requires_cost') like '%কস্ট%' and (select label_bn from public.rules where key = 'production_requires_cost') not like '%খরচ%');
select tt.chk('T1 rule recipe_self_approve: label_bn uses অ্যাপ্রুভ',
  (select label_bn from public.rules where key = 'recipe_self_approve') like '%অ্যাপ্রুভ%');
select tt.chk('T1 grant recipe_approve: label_bn = রেসিপি অ্যাপ্রুভ', (select label_bn from public.grant_defs where grant_code = 'recipe_approve') = 'রেসিপি অ্যাপ্রুভ');
-- T2 paste twice = no change at all
select md5(string_agg(key || '|' || coalesce(label_bn,'') || '|' || coalesce(label_mix,''), ';' order by key)) as m_rules from public.rules \gset
select md5(string_agg(grant_code || '|' || coalesce(label_bn,'') || '|' || coalesce(label_mix,''), ';' order by grant_code)) as m_grants from public.grant_defs \gset
select md5(string_agg(code || '|' || coalesce(label_bn,'') || '|' || coalesce(label_mix,''), ';' order by code)) as m_chk from public.setup_check_defs81 \gset
\i supabase/phase108.sql
select tt.chk('T2 paste twice: rules unchanged', (select md5(string_agg(key || '|' || coalesce(label_bn,'') || '|' || coalesce(label_mix,''), ';' order by key)) from public.rules) = :'m_rules');
select tt.chk('T2 paste twice: grant_defs unchanged', (select md5(string_agg(grant_code || '|' || coalesce(label_bn,'') || '|' || coalesce(label_mix,''), ';' order by grant_code)) from public.grant_defs) = :'m_grants');
select tt.chk('T2 paste twice: setup_check_defs81 unchanged', (select md5(string_agg(code || '|' || coalesce(label_bn,'') || '|' || coalesce(label_mix,''), ';' order by code)) from public.setup_check_defs81) = :'m_chk');
-- T3 an owner edit is never overwritten (the column no longer equals the old seed text)
update public.rules set label_bn = 'OWNER TEXT' where key = 'production_requires_cost';
\i supabase/phase108.sql
select tt.chk('T3 owner-edited label_bn survives a re-paste', (select label_bn from public.rules where key = 'production_requires_cost') = 'OWNER TEXT');
-- T4 a row that still carries the old seed text IS fixed (proves the UPDATE fires)
update public.rules set label_bn = 'উৎপাদনে কোনো উপকরণের খরচ অজানা (ফাঁকা বা ০) থাকলে: সতর্কতা / আটকানো' where key = 'production_requires_cost';
\i supabase/phase108.sql
select tt.chk('T4 a row with the old seed text is fixed by the paste', (select label_bn from public.rules where key = 'production_requires_cost') = 'উৎপাদনে কোনো উপকরণের কস্ট অজানা (ফাঁকা বা ০) থাকলে: সতর্কতা / আটকানো');
-- T5 old rows (before phase 72) are not touched: no row outside the phase 72..103 keys carries a reviewed text
select tt.chk('T5 only labels are updated: row counts unchanged', (select count(*) from public.rules) >= 1 and (select count(*) from public.grant_defs) >= 1);
-- T6 guard: a database without the phase103 marker is refused and nothing is touched
update public.rules set key = 'acct_manual_prod_in103_hold' where key = 'acct_manual_prod_in103';
update public.rules set label_bn = 'উৎপাদনে কোনো উপকরণের খরচ অজানা (ফাঁকা বা ০) থাকলে: সতর্কতা / আটকানো' where key = 'production_requires_cost';
\i supabase/phase108.sql
select tt.chk('T6 guard: with the phase103 marker missing the paste raises and changes nothing', (select label_bn from public.rules where key = 'production_requires_cost') like '%খরচ অজানা%');
update public.rules set key = 'acct_manual_prod_in103' where key = 'acct_manual_prod_in103_hold';
\i supabase/phase108.sql
select tt.chk('T6 with the marker back the paste fixes the row again', (select label_bn from public.rules where key = 'production_requires_cost') like '%কস্ট অজানা%');

select 'RESULT pass=' || count(*) filter (where ok) || ' fail=' || count(*) filter (where not ok) from tt.res;
